CREATE TABLE etl_runs (run_id int, read int, duplicates int, quarantined int, skipped int, loaded int);
INSERT INTO etl_runs VALUES (1, 7, 1, 1, 0, 5), (2, 5, 0, 1, 2, 2), (3, 5, 0, 0, 5, 1);
SELECT run_id,
       CASE WHEN read = duplicates + quarantined + skipped + loaded THEN 'yes' ELSE 'no' END AS balanced
FROM etl_runs
ORDER BY run_id;

